fn fibonacci(n: usize) -> Vec<i32> {
    // Since n >= 2, we initialize with the first two Fibonacci numbers.
    let mut fibs = Vec::with_capacity(n);
    fibs.push(0); // F(0)
    fibs.push(1); // F(1)

    for i in 2..n {
        // Fibonacci formula: F(i) = F(i-1) + F(i-2)
        let next = fibs[i - 1] + fibs[i - 2];
        fibs.push(next);
    }

    fibs
}